import { readFileSync } from "node:fs";
import { z } from "zod";

/**
 * The service-account fields the Admin SDK needs, in the camelCase shape
 * `cert()` takes. Everything else in the key file is ignored.
 */
export interface ServiceAccountCredential {
  projectId: string;
  clientEmail: string;
  privateKey: string;
}

const serviceAccountKeySchema = z.object({
  type: z.literal("service_account"),
  project_id: z.string().min(1),
  client_email: z.string().email(),
  private_key: z.string().min(1),
});

type CredentialEnv = Partial<
  Record<"FIREBASE_SERVICE_ACCOUNT_JSON" | "GOOGLE_APPLICATION_CREDENTIALS", string>
>;

/**
 * Loads the Firebase service account once, at boot (CLAUDE.md, Firestore).
 * `FIREBASE_SERVICE_ACCOUNT_JSON` wins — raw JSON, or base64 of it — otherwise
 * `GOOGLE_APPLICATION_CREDENTIALS` names the key file. Returns `null` when
 * neither is set; throws on anything malformed so a bad key fails the boot,
 * not the first Firestore call. Errors name the source, never the key itself.
 */
export function loadCredential(env: CredentialEnv): ServiceAccountCredential | null {
  const inline = env.FIREBASE_SERVICE_ACCOUNT_JSON;
  if (inline) return validate(parseInline(inline), "FIREBASE_SERVICE_ACCOUNT_JSON");

  const file = env.GOOGLE_APPLICATION_CREDENTIALS;
  if (file) return validate(parseFile(file), "GOOGLE_APPLICATION_CREDENTIALS");

  return null;
}

function parseInline(value: string): unknown {
  const decoded = Buffer.from(value, "base64").toString("utf8");
  for (const candidate of [value, decoded]) {
    try {
      return JSON.parse(candidate);
    } catch {
      // Not this encoding; try the next one.
    }
  }
  throw new Error("FIREBASE_SERVICE_ACCOUNT_JSON is neither JSON nor base64-encoded JSON");
}

function parseFile(file: string): unknown {
  let contents: string;
  try {
    contents = readFileSync(file, "utf8");
  } catch (err) {
    const code = err instanceof Error && "code" in err ? String(err.code) : "unknown";
    throw new Error(`GOOGLE_APPLICATION_CREDENTIALS: cannot read ${file} (${code})`);
  }
  try {
    return JSON.parse(contents);
  } catch {
    throw new Error(`GOOGLE_APPLICATION_CREDENTIALS: ${file} is not valid JSON`);
  }
}

function validate(raw: unknown, source: string): ServiceAccountCredential {
  const parsed = serviceAccountKeySchema.safeParse(raw);
  if (!parsed.success) {
    // Paths and messages only: zod issues never include the offending value.
    const problems = parsed.error.issues
      .map((issue) => `${issue.path.join(".") || "(root)"}: ${issue.message}`)
      .join("; ");
    throw new Error(`${source} is not a service-account key (${problems})`);
  }
  return {
    projectId: parsed.data.project_id,
    clientEmail: parsed.data.client_email,
    privateKey: parsed.data.private_key,
  };
}
import { cert, deleteApp, initializeApp } from "firebase-admin/app";
import { getFirestore, type DocumentReference, type Firestore } from "firebase-admin/firestore";
import type { ServiceAccountCredential } from "./credential.js";

export interface FirestoreHandle {
  db: Firestore;
  /** Releases the Admin SDK app and its connections (tests, shutdown). */
  close: () => Promise<void>;
}

/**
 * Opens Firestore through the Admin SDK — the only Firestore access in the
 * system; browsers have none (`firestore.rules`). `appName` lets tests open
 * their own app beside the default one.
 */
export function openFirestore(
  credential: ServiceAccountCredential,
  appName?: string,
): FirestoreHandle {
  const app = initializeApp(
    { credential: cert(credential), projectId: credential.projectId },
    appName,
  );
  const db = getFirestore(app);
  db.settings({ ignoreUndefinedProperties: true });
  return { db, close: () => deleteApp(app) };
}

/**
 * The namespace root document `ns/{namespace}` (ADR-0001). Every collection —
 * `runs`, `runs/{runId}/jobs`, `seen`, `users` — hangs off it, so a namespace
 * is one subtree that `recursiveDelete(nsDoc(...))` removes whole, and no query
 * can span namespaces.
 */
export function nsDoc(db: Firestore, namespace: string): DocumentReference {
  return db.doc(`ns/${namespace}`);
}
import type { Repo } from "@auto-apply/shared";
import type { Config } from "../config.js";
import { loadCredential } from "../firestore/credential.js";
import { openFirestore } from "../firestore/firestore.js";
import { FirestoreRepo } from "./firestore-repo.js";
import { InMemoryRepo } from "./in-memory-repo.js";

export interface Persistence {
  repo: Repo;
  kind: "firestore" | "memory";
  close: () => Promise<void>;
}

/**
 * Chooses the `Repo` at boot. A configured credential is validated now (a bad
 * key fails the boot) and selects Firestore in the configured namespace.
 * Without one, development falls back to the in-memory twin; production
 * refuses to start rather than silently losing data.
 */
export function createRepo(config: Config, appName?: string): Persistence {
  const credential = loadCredential(config);
  if (credential) {
    const handle = openFirestore(credential, appName);
    return {
      repo: new FirestoreRepo(handle.db, config.FIRESTORE_NAMESPACE),
      kind: "firestore",
      close: handle.close,
    };
  }
  if (config.NODE_ENV === "production") {
    throw new Error(
      "Refusing to start: production needs a Firestore credential " +
        "(GOOGLE_APPLICATION_CREDENTIALS or FIREBASE_SERVICE_ACCOUNT_JSON)",
    );
  }
  return { repo: new InMemoryRepo(), kind: "memory", close: async () => {} };
}
/**
 * The Firestore implementation of the `Repo` port, laid out per ADR-0001: every
 * collection hangs off the namespace root document, so nothing here builds a
 * path except through {@link nsDoc}. Reads are zod-validated against the
 * contract; funnel counts use `FieldValue.increment` and each Evaluation is its
 * own document, so concurrent pipeline steps never lose updates.
 */
import {
  FieldValue,
  type CollectionReference,
  type DocumentReference,
  type Firestore,
  type QueryDocumentSnapshot,
} from "firebase-admin/firestore";
import { z } from "zod";
import {
  ActiveRunExistsError,
  evaluationSchema,
  isRunActive,
  runSchema,
